<div class="page-heading"><div><p class="eyebrow"><?= e(t('SRI LANKA CALENDAR')) ?></p><h1><?= e(t('Sri Lanka holidays')) ?></h1><p class="muted"><?= e(t('Official dates for the year shown below. Check the linked source for later changes.')) ?></p></div><a class="btn secondary" href="/planner"><?= e(t('Back to planner')) ?></a></div>
<section class="card"><form class="inline" method="get" action="/planner/holidays"><label><?= e(t('Year')) ?><input type="number" name="year" min="2000" max="2100" value="<?= e($year) ?>" required></label><button class="secondary"><?= e(t('View year')) ?></button></form>
<?php if (!$calendar['dataset']): ?><p class="muted"><?= e(t('No verified Sri Lanka holiday dataset is bundled for')) ?> <?= e($year) ?><?= e(t('. Dates for another year are not estimated.')) ?></p><?php else: $dataset=$calendar['dataset']; ?>
<p class="footnote"><?= e($dataset['year']) ?> · <?= e($dataset['revision']) ?> <?= e(t('· Latest source published')) ?> <?= e($dataset['published_on']) ?> · <a href="<?= e($dataset['source_url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($dataset['source_title']) ?></a><?= e(t('. Base sources:')) ?> <a href="https://documents.gov.lk/view/calander/2026/2026_E.pdf" target="_blank" rel="noopener noreferrer"><?= e(t('2026 government desk calendar')) ?></a> <?= e(t('and')) ?> <a href="https://documents.gov.lk/view/extra-gazettes/2025/5/2438-22_E.pdf" target="_blank" rel="noopener noreferrer"><?= e(t('Gazette Extraordinary 2438/22')) ?></a><?= e(t('. Subject to later official variation.')) ?></p>
<p class="footnote"><?= e(t('All Saturdays and Sundays are bank holidays, even when they have no row below. This list shows named holidays only.')) ?></p>
<div class="table-wrap"><table><thead><tr><th><?= e(t('Date')) ?></th><th><?= e(t('Holiday')) ?></th><th><?= e(t('Applies to')) ?></th></tr></thead><tbody><?php foreach ($calendar['holidays'] as $holiday): ?><tr><td><?= e($holiday['date']) ?></td><td><strong><?= e($holiday['title_en']) ?></strong></td><td><?= e(implode(' · ',array_filter([$holiday['is_public'] ? t('Public') : null,'Bank',$holiday['is_mercantile'] ? t('Mercantile') : null,$holiday['is_poya'] ? t('Poya') : null]))) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?></section>
<section class="card"><h2><?= e(t('Add a corrected local entry')) ?></h2><p class="muted"><?= e(t('Use this for an official holiday correction. The source and revision stay attached to the record.')) ?></p><div class="form-grid"><form method="post" action="/planner/holidays/holiday"><?= csrf_field() ?><input type="hidden" name="year" value="<?= e($year) ?>"><h3><?= e(t('Holiday')) ?></h3><label><?= e(t('Date')) ?><input type="date" name="date" required></label><label><?= e(t('English name')) ?><input name="title_en" required></label><label><?= e(t('Sinhala name')) ?><input name="title_si"></label><label><?= e(t('Tamil name')) ?><input name="title_ta"></label><label><?= e(t('Jurisdiction')) ?><input name="jurisdiction" value="Sri Lanka"></label><label><input type="checkbox" name="is_public" checked> <?= e(t('Public')) ?></label><label><input type="checkbox" name="is_bank" checked> <?= e(t('Bank')) ?></label><label><input type="checkbox" name="is_mercantile"> <?= e(t('Mercantile')) ?></label><label><input type="checkbox" name="is_poya"> <?= e(t('Poya')) ?></label><button><?= e(t('Save holiday')) ?></button></form></div></section>
